  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is i?', 'The imaginary unit, defined by i² = −1.', 1),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is a complex number?', 'A number of the form z = a + bi, where a and b are real.', 2),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What are Re(z) and Im(z) for z = 3 − 4i?', 'Re(z) = 3 and Im(z) = −4.', 3),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is the complex conjugate of z = a + bi?', 'z* = a − bi.', 4),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Simplify i³ and i⁴.', 'i³ = −i and i⁴ = 1.', 5),
