  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Solve z² − 2z + 5 = 0.', 'z = (2 ± √(4 − 20))/2 = 1 ± 2i.', 12),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is an Argand diagram?', 'A diagram representing complex numbers as points, with the real part on the horizontal axis and the imaginary part on the vertical axis.', 13),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'How is z* shown on an Argand diagram?', 'As the reflection of z in the real axis.', 14),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What does |z − a| represent?', 'The distance from z to the point a on the Argand diagram.', 15),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Describe the locus |z − 2 − i| = 3.', 'A circle with centre (2, 1) and radius 3.', 16),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Describe the locus |z − 1| = |z + i|.', 'The perpendicular bisector of the points 1 and −i.', 17),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Describe the locus arg(z − 1) = π/4.', 'A half-line from (1, 0) at angle π/4 to the positive real axis, not including the point 1.', 18),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What does |z| < 2 represent?', 'The interior of a circle centred at the origin with radius 2.', 19),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'Describe the region |z − 3| ≤ |z + 1|.', 'The points closer to 3 than to −1: Re(z) ≥ 1.', 20),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What does arg z = θ represent?', 'A half-line from the origin at angle θ.', 21),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is Euler''s formula?', 'e^(iθ) = cos θ + i sin θ.', 22),
  ('Further Mathematics', 'OCR A', 'alevel', '1.1', 'Complex Numbers', 'What is the exponential form of a complex number?', 'z = re^(iθ).', 23),
